// Code node "Split emails" (mode: run once for all items).
// Input: the emails.json file read from disk (binary "data"). Output: one item per email.
// The "expected" answer that test.js uses to grade the run is removed here, so the model never sees it.

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const emails = JSON.parse(buffer.toString('utf8'));

return emails.map(({ id, from, subject, body }) => ({ json: { id, from, subject, body } }));

// Code node "Build model request" (mode: run once for all items).
// Input: one email per item. Output: the same email plus json.request, the Chat Completions body
// with a strict JSON schema, so the model can only answer in the agreed shape.

const MODEL = 'gpt-4.1-mini-2025-04-14';
const CATEGORIES = ['quote_request', 'complaint_or_incident', 'scheduling', 'supplier_invoice',
  'customer_admin', 'spam_or_marketing', 'other'];

const SYSTEM = `You triage incoming emails for a small renovation company.
Classify each email into exactly one category:
- quote_request: someone asks for a price, a visit or a budget for new work.
- complaint_or_incident: something went wrong: damage, a leak, noise, dust, a complaint about the work or the workers.
- scheduling: confirm, move or cancel a visit or an appointment.
- supplier_invoice: an invoice or a statement sent by a supplier.
- customer_admin: a customer asks for an invoice, a document or a payment detail.
- spam_or_marketing: unsolicited sales or marketing.
- other: anything else.
Urgency: high if there is ongoing damage or a safety risk that needs action today; low for spam or marketing; otherwise normal.
Write a one-sentence summary for the office.
Draft a short, polite reply in the same language as the email, signed "The office team".
Greet the sender by the first name they sign with; if there is none, write "Hello". Never guess a title or gender (no Mr, Mrs, Ms, Sir, Madam).
Never promise prices, dates, amounts or responsibility for damage: write placeholders such as [date], [time] or [price] where a person must decide.
For spam_or_marketing the reply_draft is an empty string.
needs_human is true for complaint_or_incident, for anything with high urgency, and whenever you are unsure.`;

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['category', 'urgency', 'summary', 'needs_human', 'reply_draft'],
  properties: {
    category: { type: 'string', enum: CATEGORIES },
    urgency: { type: 'string', enum: ['high', 'normal', 'low'] },
    summary: { type: 'string' },
    needs_human: { type: 'boolean' },
    reply_draft: { type: 'string' },
  },
};

return $input.all().map(({ json: email }) => ({
  json: {
    ...email,
    request: {
      model: MODEL,
      temperature: 0,
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: `From: ${email.from}\nSubject: ${email.subject}\n\n${email.body}` },
      ],
      response_format: { type: 'json_schema', json_schema: { name: 'email_triage', strict: true, schema } },
    },
  },
}));

// Code node "Check model answer" (mode: run once for all items).
// Input: one Chat Completions response per email, in the same order as "Build model request".
// Output: one row per email. The model's answer is checked against the agreed shape, and the
// safety rules are applied here in code, not trusted to the model:
//   - complaints and high urgency always go to a person;
//   - an answer that does not parse or does not fit becomes category "other" and goes to a person;
//   - nothing is ever sent: every reply is a draft waiting for approval.

const emails = $('Build model request').all();
const CATEGORIES = ['quote_request', 'complaint_or_incident', 'scheduling', 'supplier_invoice',
  'customer_admin', 'spam_or_marketing', 'other'];
const URGENCY = ['high', 'normal', 'low'];

function readAnswer(response) {
  try {
    const a = JSON.parse(response?.choices?.[0]?.message?.content ?? '');
    const ok = CATEGORIES.includes(a.category) && URGENCY.includes(a.urgency) &&
      typeof a.summary === 'string' && typeof a.needs_human === 'boolean' && typeof a.reply_draft === 'string';
    return ok ? a : null;
  } catch {
    return null;
  }
}

return $input.all().map((item, i) => {
  const email = emails[i]?.json ?? {};
  const answer = readAnswer(item.json);
  const checks = [];
  let row;
  if (!answer) {
    checks.push('model answer did not fit the agreed format');
    row = { category: 'other', urgency: 'normal', summary: '', needs_human: true, reply_draft: '' };
  } else {
    row = { ...answer };
    if ((row.category === 'complaint_or_incident' || row.urgency === 'high') && !row.needs_human) {
      row.needs_human = true;
      checks.push('sent to a person by rule (complaint or high urgency)');
    }
  }
  return {
    json: {
      'ID': email.id,
      'From': email.from,
      'Subject': email.subject,
      'Category': row.category,
      'Urgency': row.urgency,
      'Needs a person': row.needs_human ? 'yes' : 'no',
      'Summary': row.summary,
      'Reply draft': row.reply_draft,
      'Reply status': row.reply_draft ? 'DRAFT, waiting for approval' : 'no reply',
      'Checks': checks.join('; '),
      'Model': item.json?.model ?? '',
      'Tokens': item.json?.usage?.total_tokens ?? '',
    },
  };
});

// Code node "Build approval list" (mode: run once for all items).
// Input: the checked rows. Output: one item with json.markdown, the list a person reads to approve,
// edit or discard each draft. Urgent items and items for a person come first.

const rows = $input.all().map(i => i.json);
const rank = r => (r['Urgency'] === 'high' ? 0 : r['Needs a person'] === 'yes' ? 1 : 2);
const sorted = [...rows].sort((a, b) => rank(a) - rank(b));

const lines = [
  '# Inbox triage: drafts waiting for approval',
  '',
  `${rows.length} emails. ${rows.filter(r => r['Needs a person'] === 'yes').length} need a person. Nothing has been sent.`,
  '',
];
for (const r of sorted) {
  lines.push(`## ${r['Urgency'] === 'high' ? '🔴 ' : ''}${r['Subject']}`);
  lines.push('');
  lines.push(`- **From:** ${r['From']} · **Category:** ${r['Category']} · **Urgency:** ${r['Urgency']} · **Needs a person:** ${r['Needs a person']}`);
  lines.push(`- **Summary:** ${r['Summary']}`);
  if (r['Checks']) lines.push(`- **Checks:** ${r['Checks']}`);
  lines.push('');
  if (r['Reply draft']) {
    lines.push('> ' + r['Reply draft'].split('\n').join('\n> '));
    lines.push('');
    lines.push('*Status: draft, waiting for approval.*');
  } else {
    lines.push('*No reply drafted.*');
  }
  lines.push('');
}

return [{ json: { markdown: lines.join('\n') } }];
